import React, { useEffect, useRef, useState } from 'react';
import { OBJECT_CATALOG, OBJECT_CATALOG_BY_TYPE } from './objectCatalog';

// Simple interactive canvas editor for UIN objects (human, tree, car, building, ...)
// - Renders a top-down view based on canvas.bounds and objects[].position
// - Lets the user add objects and drag existing ones; writes back into UIN JSON

const VIEW_WIDTH = 600;
const VIEW_HEIGHT = 400;

const TOOL_NONE = 'none';

function worldToScreen(pos, bounds) {
  const xRange = bounds.x[1] - bounds.x[0] || 1;
  const zRange = bounds.z[1] - bounds.z[0] || 1;

  const sx = ((pos.x - bounds.x[0]) / xRange) * VIEW_WIDTH;
  const sy = VIEW_HEIGHT - ((pos.z - bounds.z[0]) / zRange) * VIEW_HEIGHT;
  return { x: sx, y: sy };
}

function hitTestObject(obj, bounds, x, y) {
  const screenPos = worldToScreen(obj.position, bounds);
  const r = 14; // hit radius
  const dx = x - screenPos.x;
  const dy = y - screenPos.y;
  return dx * dx + dy * dy <= r * r;
}

export default function CanvasEditor({ uinJSON, onChange }) {
  const canvasRef = useRef(null);
  const [tool, setTool] = useState(TOOL_NONE); // either 'none' or one of OBJECT_CATALOG types
  const [dragState, setDragState] = useState(null);
  const [localError, setLocalError] = useState('');

  // Parse once per render; for editing we always go through JSON d App
  let doc = null;
  try {
    doc = JSON.parse(uinJSON || '{}');
  } catch (e) {
    doc = null;
  }

  // Derived safe structure
  const bounds = doc?.canvas?.bounds || { x: [-10, 10], y: [-10, 10], z: [-5, 5] };
  const objects = Array.isArray(doc?.objects) ? doc.objects : [];

  // Rendering
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !doc) return;

    // jsdom in tests does not implement canvas.getContext by default
    const ctx = typeof canvas.getContext === 'function' ? canvas.getContext('2d') : null;
    if (!ctx) return;

    ctx.clearRect(0, 0, VIEW_WIDTH, VIEW_HEIGHT);

    // Background
    ctx.fillStyle = '#111827';
    ctx.fillRect(0, 0, VIEW_WIDTH, VIEW_HEIGHT);

    // Grid
    ctx.strokeStyle = '#1f2937';
    ctx.lineWidth = 1;
    for (let i = 1; i < 6; i++) {
      const x = (VIEW_WIDTH / 6) * i;
      const y = (VIEW_HEIGHT / 6) * i;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, VIEW_HEIGHT);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(VIEW_WIDTH, y);
      ctx.stroke();
    }

    // Objects
    objects.forEach((obj) => {
      if (!obj.position) return;
      const { x, y } = worldToScreen(obj.position, bounds);

      const spec = OBJECT_CATALOG_BY_TYPE[obj.type] || {};
      const color = spec.color || '#22c55e';

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x, y, 10, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = '#e5e7eb';
      ctx.font = '10px system-ui';
      ctx.textAlign = 'center';
      ctx.fillText(obj.type || '?', x, y - 14);
    });
  }, [uinJSON]);

  const handleCanvasClick = (evt) => {
    if (!doc) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const x = evt.clientX - rect.left;
    const y = evt.clientY - rect.top;

    if (tool === TOOL_NONE) return;

    // Convert screen -> world (x,z)
    const xRange = bounds.x[1] - bounds.x[0] || 1;
    const zRange = bounds.z[1] - bounds.z[0] || 1;
    const wx = bounds.x[0] + (x / VIEW_WIDTH) * xRange;
    const wz = bounds.z[0] + ((VIEW_HEIGHT - y) / VIEW_HEIGHT) * zRange;

    const newDoc = { ...doc, objects: [...objects] };
    const idSuffix = objects.length + 1;

    const spec = OBJECT_CATALOG_BY_TYPE[tool];
    const measurements = spec?.defaultMeasurements || {};

    const base = {
      id: `${tool}${idSuffix}`,
      type: tool,
      position: { x: wx, y: 0, z: wz },
      ...(spec?.promptKeyword ? { description: spec.promptKeyword } : {}),
      ...(Object.keys(measurements).length
        ? { measurements }
        : {}),
    };

    newDoc.objects.push(base);
    try {
      onChange(JSON.stringify(newDoc, null, 2));
      setLocalError('');
    } catch (e) {
      setLocalError(e.message);
    }
  };

  const handleMouseDown = (evt) => {
    if (!doc) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const x = evt.clientX - rect.left;
    const y = evt.clientY - rect.top;

    // Find top-most hit
    for (let i = objects.length - 1; i >= 0; i -= 1) {
      const obj = objects[i];
      if (obj.position && hitTestObject(obj, bounds, x, y)) {
        setDragState({ index: i, offset: { x, y } });
        return;
      }
    }
  };

  const handleMouseMove = (evt) => {
    if (!doc || !dragState) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const x = evt.clientX - rect.left;
    const y = evt.clientY - rect.top;

    const xRange = bounds.x[1] - bounds.x[0] || 1;
    const zRange = bounds.z[1] - bounds.z[0] || 1;
    const wx = bounds.x[0] + (x / VIEW_WIDTH) * xRange;
    const wz = bounds.z[0] + ((VIEW_HEIGHT - y) / VIEW_HEIGHT) * zRange;

    const newDoc = { ...doc, objects: [...objects] };
    const obj = { ...newDoc.objects[dragState.index] };
    obj.position = { ...(obj.position || { x: 0, y: 0, z: 0 }), x: wx, z: wz };
    newDoc.objects[dragState.index] = obj;

    try {
      onChange(JSON.stringify(newDoc, null, 2));
      setLocalError('');
    } catch (e) {
      setLocalError(e.message);
    }
  };

  const handleMouseUp = () => {
    setDragState(null);
  };

  const disabled = !doc;

  return (
    <div className="bg-gray-800 rounded-lg p-4 flex flex-col h-full">
      <div className="flex items-center justify-between mb-3">
        <h2 className="text-lg font-semibold">Canvas Editor (Top-Down)</h2>
        <div className="flex gap-2 text-xs">
          {OBJECT_CATALOG.map((entry, idx) => (
            <button
              key={`${entry.type}-${idx}`}
              type="button"
              onClick={() => setTool(entry.type)}
              className={`px-2 py-1 rounded border ${tool === entry.type ? 'border-blue-400 bg-blue-600' : 'border-gray-600 bg-gray-700'}`}
            >
              + {entry.label}
            </button>
          ))}
          <button
            type="button"
            onClick={() => setTool(TOOL_NONE)}
            className={`px-2 py-1 rounded border ${tool === TOOL_NONE ? 'bg-gray-600 border-gray-500' : 'bg-gray-700 border-gray-600'}`}
          >
            Select
          </button>
        </div>
      </div>

      {disabled && (
        <div className="text-xs text-red-300 mb-2">
          Invalid JSON d Canvas editor disabled.
        </div>
      )}

      <div className="relative border border-gray-700 rounded bg-gray-900 flex-1 flex items-center justify-center">
        <canvas
          ref={canvasRef}
          width={VIEW_WIDTH}
          height={VIEW_HEIGHT}
          className={`max-w-full rounded ${disabled ? 'opacity-40 cursor-not-allowed' : 'cursor-crosshair'}`}
          onClick={disabled ? undefined : handleCanvasClick}
          onMouseDown={disabled ? undefined : handleMouseDown}
          onMouseMove={disabled ? undefined : handleMouseMove}
          onMouseUp={disabled ? undefined : handleMouseUp}
          onMouseLeave={disabled ? undefined : handleMouseUp}
        />
      </div>

      {localError && (
        <div className="mt-2 text-xs text-red-300">{localError}</div>
      )}

      <p className="mt-2 text-xs text-gray-400">
        Tipp: W�e4hle oben ein Objekt und klicke auf die Fl�e4che, um es zu platzieren. Ziehe bestehende Marker, um Positionen zu verschieben.
      </p>
    </div>
  );
}
